export function TimelineItem(e,n){const t=n?n.color:"#FF6B35";return`<div class="timeline-item" data-era-id="${e.eraId}" style="--item-color: ${t}">\n    <div class="timeline-dot" style="background: ${t}"></div>\n    <div class="timeline-content">\n      <span class="timeline-year">${e.year}</span>\n      <h4 class="timeline-title">${n?n.name:e.eraId}</h4>\n      <p class="timeline-then"><strong>Then:</strong> ${e.then}</p>\n      <p class="timeline-now"><strong>Today's equivalent:</strong> ${e.now}</p>\n    </div>\n  </div>`}